from collections import deque


def can_finish(adj: list[list[int]]) -> bool:
    indegree = [0] * len(adj)
    for course in range(len(adj)):
        for after in adj[course]:
            indegree[after] += 1
    queue = deque(course for course in range(len(adj)) if indegree[course] == 0)
    taken = 0
    while queue:
        course = queue.popleft()
        taken += 1
        for after in adj[course]:
            indegree[after] -= 1
            if indegree[after] == 0:
                queue.append(after)
    return taken == len(adj)


# adj[u] lists the courses that need course u first.
n, m = map(int, input().split())
adj: list[list[int]] = [[] for _ in range(n)]
for _ in range(m):
    u, v = map(int, input().split())
    adj[u].append(v)
print("true" if can_finish(adj) else "false")

