    static boolean canFinish(List<List<Integer>> adj) {
        int n = adj.size();
        int[] indegree = new int[n];
        for (List<Integer> edges : adj) {
            for (int after : edges) {
                indegree[after]++;
            }
        }
        Queue<Integer> queue = new ArrayDeque<>();
        for (int course = 0; course < n; course++) {
            if (indegree[course] == 0) {
                queue.add(course);
            }
        }
        int taken = 0;
        while (!queue.isEmpty()) {
            int course = queue.poll();
            taken++;
            for (int after : adj.get(course)) {
                indegree[after]--;
                if (indegree[after] == 0) {
                    queue.add(after);
                }
            }
        }
        return taken == n;
    }

