	for _, edges := range adj {
		for _, after := range edges {
			indegree[after]++
		}
	}
	queue := []int{}
	for course, count := range indegree {
		if count == 0 {
			queue = append(queue, course)
		}
	}
	for head := 0; head < len(queue); head++ {
		for _, after := range adj[queue[head]] {
			indegree[after]--
			if indegree[after] == 0 {
				queue = append(queue, after)
			}
		}
