const input = readFileSync(0, "utf8");

function canFinish(adj: number[][]): boolean {
  const indegree: number[] = adj.map(() => 0);
  for (const edges of adj) {
    for (const after of edges) {
      indegree[after] = (indegree[after] ?? 0) + 1;
    }
  }
  const queue: number[] = [];
  indegree.forEach((count, course) => {
    if (count === 0) {
      queue.push(course);
    }
  });
  let head = 0;
  while (head < queue.length) {
    const course = queue[head++];
    if (course === undefined) {
      break;
    }
    for (const after of adj[course] ?? []) {
      const count = (indegree[after] ?? 0) - 1;
      indegree[after] = count;
      if (count === 0) {
        queue.push(after);
      }
    }
  }
  // The queue keeps every course it took, so its length is how many you took.
  return queue.length === adj.length;
}

